    publication={'title':'; '.join(z[0] for z in pubs),'authors':'; '.join(dict.fromkeys(z[1] for z in pubs)),'venue':'; '.join(z[2] for z in pubs),'authoritative_version':'; '.join(k+': '+', '.join(pn['sha256'] for pn in sources[k]['files']) for k in keys),'locator':locator,'corrections':limits}
    u.update(id=id,passages=[id+'-APPLICATION'],reason='Instantiate the specified published input under the displayed hypotheses. '+limits,shared_contract_justification='Same source specialization shared only by the explicitly listed theta clauses; each local deduction remains separate.',inline_argument=p)
    u['supplier'].update(kind='published_external',application_id=None,location=p,statement=statement,publication=publication)
    co=c['connection'];co.update(use_id=id,use_sha256=digest(u),supplier_passage_role='application',available_assertion=copy.deepcopy(x),needed_assertion=copy.deepcopy(x),required_capabilities=[id],available_capabilities=[id],derived_capabilities=[],consumer_locations=[p]);co['connecting_derivation'].update(kind='identification',location=p,application_id=None,output_assertion=copy.deepcopy(x));co['adverse_cases'].update(reason=limits,evidence=[p['pin']])
    c['initial_mapping']=[{'id':'HIST-theta-T'+str(n).zfill(3),'part':'Only this imported assertion: '+statement} for n in targets]
    c['retained_separate_inputs']=['The target theta clause local argument and its other named hypotheses.',limits]
    c.pop('prior_review',None)
    c['reuse_scope']='Retained published-source specializations and prior bounded source-family checks; current clause comparison still required. The location is an application, not a verbatim external-source passage.'
    components.append(c);checks.append({'id':id,'source_hashes_verified':True,'use_digest_valid':digest(u)==co['use_sha256']})
